function newf(date){const o=date.getTimezoneOffset()*60000;date.setTime(date.getTime()-o);const s=date.toISOString().substr(0,10),t=s.split('-');return new Date(Number(t[0]),Number(t[1])-1,Number(t[2]))}
const fmt=d=>d.getFullYear()+'-'+(d.getMonth()+1)+'-'+d.getDate();
const utcMs=Date.UTC(2019,8,20); // python-serialized 2019-09-20
const str='Mon Sep 16 2019';     // toDateString after a pick
console.log(process.env.TZ,
 'ms-in old',fmt(oldf(new Date(utcMs))),'new',fmt(newf(new Date(utcMs))),'(want 2019-9-20)',
 '| str-in old',fmt(oldf(new Date(str))),'new',fmt(newf(new Date(str))),'(want 2019-9-16)');
EOF
