const fmt=d=>d.getFullYear()+'-'+(d.getMonth()+1)+'-'+d.getDate();
console.log(process.env.TZ, fmt(fix(Date.UTC(2019,8,20))), fmt(fix('Mon Sep 16 2019')), fmt(fix(Date.UTC(2019,8,20,15,30))));
EOF
